import json
from pathlib import Path
import sys
sys.path.insert(0, "/home/khoi/Projects/oxide/scripts/agent_eval")
import tasks

HOME = Path.home()
auth = json.loads((HOME / ".codex" / "auth.json").read_text())
def leaves(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from leaves(v, f"{path}.{k}")
    elif isinstance(node, str) and len(node) >= 12:
        yield path, node.encode()
secrets = list(leaves(auth))
hits = {path: [] for path, _ in secrets}
scanned = 0
for p in tasks.CACHE.rglob("*"):
    if not p.is_file() or p.is_symlink():
        continue
    try:
        data = p.read_bytes() if p.stat().st_size < 20_000_000 else b""
    except OSError:
        continue
    scanned += 1
    for path, value in secrets:
        if value in data:
            hits[path].append(str(p.relative_to(tasks.CACHE)))
print("files scanned:", scanned)
for path, found in hits.items():
    print(f"codex login {path:28s} hits={len(found)}", found[:2])
